// Fluid-only conceptual circuit editor. Independent graph, shared project persistence.
const fluidSelection=new Set();let fluidSelected=null,fluidClipboard=null,fluidPendingPort=null,fluidBoxMode=false,fluidAssembly=true;
function fluidCircuit(){return project.fluidify||(project.fluidify=FluidifyModel.empty());}
function commitFluid(action){project.fluidify=FluidifyModel.validate(fluidCircuit());changed('Fluidify: '+action);}
function fluidPoint(n,portId){const index=n.ports.findIndex(p=>p.id===portId),p=n.ports[index];return {x:n.x+(p?.direction==='in'?0:228),y:n.y+81+index*30,top:n.y};}
function fluidCurve(a,b){if(b.x<=a.x){const lane=Math.min(a.top,b.top)-45;return `M ${a.x} ${a.y} C ${a.x+60} ${a.y},${a.x+60} ${lane},${a.x+40} ${lane} L ${b.x-40} ${lane} C ${b.x-60} ${lane},${b.x-60} ${b.y},${b.x} ${b.y}`;}const reach=Math.max(50,Math.abs(b.x-a.x)*.45);return `M ${a.x} ${a.y} C ${a.x+reach} ${a.y},${b.x-reach} ${b.y},${b.x} ${b.y}`;}
function paintFluidMap(){
  const circuit=fluidCircuit(),world=$('#fluidWorld');if(!world)return;
  world.style.transform=`translate(${circuit.viewport.x}px,${circuit.viewport.y}px) scale(${circuit.viewport.scale})`;
  $('#fluidZoomLabel').textContent=Math.round(circuit.viewport.scale*100)+'%';
  for(const card of world.querySelectorAll('[data-fluid-node]')){const n=circuit.nodes.find(n=>n.id===card.dataset.fluidNode);if(!n)continue;card.style.left=n.x+'px';card.style.top=n.y+'px';card.classList.toggle('selected',fluidSelection.has(n.id));}
  $('#fluidLines').innerHTML=`<defs><marker id="fluidArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#4489a0"/></marker></defs>`+(fluidAssembly?circuit.nodes.filter(n=>n.parent).map(n=>{const p=circuit.nodes.find(p=>p.id===n.parent);return `<path class="fluid-assembly-line" d="M ${p.x+114} ${p.y+FluidifyModel.bounds(p).height} L ${n.x+114} ${n.y}"/>`;}).join(''):'')+circuit.connections.map(w=>{const a=circuit.nodes.find(n=>n.id===w.from.component),b=circuit.nodes.find(n=>n.id===w.to.component);return `<path class="fluid-wire" data-fluid-wire="${esc(w.id)}" d="${fluidCurve(fluidPoint(a,w.from.port),fluidPoint(b,w.to.port))}" marker-end="url(#fluidArrow)"><title>${esc(a.name+' → '+b.name+' · click to delete hose')}</title></path>`;}).join('');
  $('#fluidSelectionCount').textContent=fluidSelection.size+' selected';
}
function addFluidPart(kind,point=null){try{const circuit=fluidCircuit();if(!point){const i=circuit.nodes.length;point={x:80+(i%3)*310,y:80+Math.floor(i/3)*260};}const n=FluidifyModel.add(circuit,kind,point);fluidSelected=n.id;fluidSelection.clear();fluidSelection.add(n.id);commitFluid('added '+n.name);}catch(e){toast(e.message);}}
function fluidZoom(multiplier,anchor=null){const canvas=$('#fluidViewport'),v=fluidCircuit().viewport;anchor=anchor||{x:canvas.clientWidth/2,y:canvas.clientHeight/2};const scale=Math.max(.15,Math.min(3,v.scale*multiplier));v.x=Math.max(-100000,Math.min(100000,anchor.x-(anchor.x-v.x)*scale/v.scale));v.y=Math.max(-100000,Math.min(100000,anchor.y-(anchor.y-v.y)*scale/v.scale));v.scale=scale;paintFluidMap();persist();}
function fitFluid(){const c=fluidCircuit(),canvas=$('#fluidViewport');if(!c.nodes.length){c.viewport={x:40,y:40,scale:1};}else{const boxes=c.nodes.map(FluidifyModel.bounds),x=Math.min(...boxes.map(b=>b.x))-35,y=Math.min(...boxes.map(b=>b.y))-35,w=Math.max(...boxes.map(b=>b.x+b.width))-x+35,h=Math.max(...boxes.map(b=>b.y+b.height))-y+35,scale=Math.max(.15,Math.min(1.25,canvas.clientWidth/w,canvas.clientHeight/h));c.viewport={x:(canvas.clientWidth-w*scale)/2-x*scale,y:(canvas.clientHeight-h*scale)/2-y*scale,scale};}paintFluidMap();persist();}
function renderFluidInspector(){
  const circuit=fluidCircuit(),n=circuit.nodes.find(n=>n.id===fluidSelected),panel=$('#fluidInspector');
  if(!n){panel.innerHTML='<h3>Fluid component details</h3><p class="fluid-help">Add a fluid mechanical part, then select it to edit ports, assembly parent and specifications. Click an outlet followed by an inlet to connect a hose.</p>';return;}
  const blocked=FluidifyModel.descendants(circuit,n.id);
  panel.innerHTML=`<h3>${esc(n.name)}</h3><form id="fluidPartForm"><label>Name<input name="name" required maxlength="200" value="${esc(n.name)}"></label><label>Model / part number<input name="model" maxlength="200" value="${esc(n.model)}"></label><label>Assembly parent<select name="parent"><option value="">Circuit root</option>${circuit.nodes.filter(p=>!blocked.has(p.id)).map(p=>`<option value="${esc(p.id)}" ${p.id===n.parent?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Quantity<input type="number" name="quantity" min="1" max="100000" required value="${n.quantity}"></label><label>Fluid / medium<input name="medium" maxlength="80" placeholder="Water, air, hydraulic oil…" value="${esc(n.medium)}"></label><label>Maximum pressure (bar)<input name="maxPressureBar" type="number" min="0" step="any" value="${n.maxPressureBar??''}" placeholder="Unknown"></label><label>Flow rating (L/min)<input name="flowLMin" type="number" min="0" step="any" value="${n.flowLMin??''}" placeholder="Unknown"></label><label>Bore / hose ID (mm)<input name="boreMm" type="number" min="0" step="any" value="${n.boreMm??''}" placeholder="Unknown"></label><label class="fluid-form-wide">Notes<textarea name="notes" maxlength="6000">${esc(n.notes)}</textarea></label><section class="fluid-form-wide"><h3>Ports</h3><div id="fluidPortRows"></div><button type="button" class="button" id="fluidAddPort">＋ Port</button><p class="fluid-help">One hose per port. Use a tee/junction to branch. Removing a port also removes its hose.</p></section><p class="fluid-error fluid-form-wide" id="fluidPartError" role="alert"></p><div class="fluid-actions fluid-form-wide"><button class="button primary" type="submit">Save component</button><button class="button" type="button" id="fluidDuplicate">Duplicate</button><button class="button danger" type="button" id="fluidRemove">Remove selected</button></div></form>`;
  const row=p=>{const el=document.createElement('div');el.className='fluid-port-edit';el.dataset.portId=p.id;el.innerHTML=`<input data-port-name required maxlength="80" aria-label="Port name" value="${esc(p.name)}"><select data-port-direction aria-label="Port direction">${['in','out','bidirectional'].map(d=>`<option ${d===p.direction?'selected':''}>${d}</option>`).join('')}</select><button type="button" aria-label="Remove port">×</button>`;el.querySelector('button').onclick=()=>el.remove();$('#fluidPortRows').append(el);};n.ports.forEach(row);
  $('#fluidAddPort').onclick=()=>{if($('#fluidPortRows').children.length>=24)return toast('Maximum 24 ports per component.');row({id:FluidifyModel.id(),name:'Port '+($('#fluidPortRows').children.length+1),direction:'bidirectional'});};
  $('#fluidPartForm').onsubmit=e=>{e.preventDefault();try{const form=new FormData(e.target),next=structuredClone(circuit),edited=next.nodes.find(p=>p.id===n.id);for(const key of ['name','model','medium','notes'])edited[key]=String(form.get(key)).trim();edited.parent=form.get('parent')||null;edited.quantity=Number(form.get('quantity'));for(const key of ['maxPressureBar','flowLMin','boreMm'])edited[key]=form.get(key)===''?null:Number(form.get(key));edited.ports=[...$('#fluidPortRows').children].map(el=>({id:el.dataset.portId,name:el.querySelector('[data-port-name]').value.trim(),direction:el.querySelector('[data-port-direction]').value}));const ports=new Set(edited.ports.map(p=>p.id));next.connections=next.connections.filter(c=>(c.from.component!==n.id||ports.has(c.from.port))&&(c.to.component!==n.id||ports.has(c.to.port)));project.fluidify=FluidifyModel.validate(next);fluidPendingPort=null;commitFluid('updated '+edited.name);}catch(error){$('#fluidPartError').textContent=error.message;}};
  $('#fluidDuplicate').onclick=()=>duplicateFluidSelection();$('#fluidRemove').onclick=()=>removeFluidSelection();
}
function copyFluidSelection(){const c=fluidCircuit();fluidClipboard=structuredClone({nodes:c.nodes.filter(n=>fluidSelection.has(n.id)),connections:c.connections});}
function pasteFluidSelection(){if(!fluidClipboard?.nodes.length)return;try{const copies=FluidifyModel.duplicate(fluidCircuit(),fluidClipboard);fluidSelection.clear();copies.forEach(n=>fluidSelection.add(n.id));fluidSelected=copies[0]?.id;fluidClipboard=structuredClone({nodes:copies,connections:fluidCircuit().connections});commitFluid('pasted fluid components');}catch(e){toast(e.message);}}
function duplicateFluidSelection(){copyFluidSelection();pasteFluidSelection();}
function removeFluidSelection(){if(!fluidSelection.size)return;FluidifyModel.remove(fluidCircuit(),fluidSelection);fluidSelection.clear();fluidSelected=null;fluidPendingPort=null;commitFluid('removed fluid components; child parts retained');}
function bindFluidCanvas(){
  const canvas=$('#fluidViewport'),circuit=fluidCircuit();let drag=null;
  const worldPoint=e=>{const r=canvas.getBoundingClientRect(),v=circuit.viewport;return {x:(e.clientX-r.left-v.x)/v.scale,y:(e.clientY-r.top-v.y)/v.scale};};
  canvas.onwheel=e=>{e.preventDefault();const r=canvas.getBoundingClientRect();fluidZoom(Math.exp(-e.deltaY*.0015),{x:e.clientX-r.left,y:e.clientY-r.top});};
  canvas.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';};canvas.ondrop=e=>{e.preventDefault();const kind=e.dataTransfer.getData('application/x-partmap-fluid');if(kind)addFluidPart(kind,worldPoint(e));else toast('Fluidify accepts fluid mechanical parts from its own palette.');};
  canvas.onpointerdown=e=>{
    if(e.button!==0)return;
    const port=e.target.closest('[data-fluid-port]');if(port){e.preventDefault();const endpoint={component:port.dataset.component,port:port.dataset.fluidPort};if(!fluidPendingPort){fluidPendingPort=endpoint;$('#fluidFlowStatus').textContent='Select the receiving inlet / bidirectional port. Esc cancels.';port.classList.add('pending');}else{try{FluidifyModel.connect(circuit,fluidPendingPort,endpoint);fluidPendingPort=null;commitFluid('connected fluid ports');}catch(error){$('#fluidFlowStatus').textContent=error.message;}}return;}
    const wire=e.target.closest('[data-fluid-wire]');if(wire){circuit.connections=circuit.connections.filter(c=>c.id!==wire.dataset.fluidWire);commitFluid('removed hose connection');return;}
    const card=e.target.closest('[data-fluid-node]'),point=worldPoint(e);
    if(card){const id=card.dataset.fluidNode;if(e.ctrlKey||e.metaKey){fluidSelection.has(id)?fluidSelection.delete(id):fluidSelection.add(id);}else if(!fluidSelection.has(id)){fluidSelection.clear();fluidSelection.add(id);}fluidSelected=id;renderFluidInspector();paintFluidMap();drag={type:'nodes',start:point,positions:circuit.nodes.filter(n=>fluidSelection.has(n.id)).map(n=>({id:n.id,x:n.x,y:n.y})),moved:false};}
    else if(fluidBoxMode||e.shiftKey){drag={type:'box',start:point,prior:e.ctrlKey||e.metaKey?new Set(fluidSelection):new Set()};$('#fluidSelectRect').hidden=false;}
    else drag={type:'pan',x:e.clientX,y:e.clientY,v:{...circuit.viewport},moved:false};
    canvas.setPointerCapture(e.pointerId);
  };
  canvas.onpointermove=e=>{if(!drag)return;const point=worldPoint(e);
    if(drag.type==='pan'){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.moved=drag.moved||Math.abs(dx)+Math.abs(dy)>3;circuit.viewport.x=Math.max(-100000,Math.min(100000,drag.v.x+dx));circuit.viewport.y=Math.max(-100000,Math.min(100000,drag.v.y+dy));}
    if(drag.type==='nodes'){const dx=point.x-drag.start.x,dy=point.y-drag.start.y;drag.moved=drag.moved||Math.abs(dx)+Math.abs(dy)>2;for(const p of drag.positions){const n=circuit.nodes.find(n=>n.id===p.id);n.x=Math.max(-99000,Math.min(99000,p.x+dx));n.y=Math.max(-99000,Math.min(99000,p.y+dy));}}
    if(drag.type==='box'){const rect={x:Math.min(point.x,drag.start.x),y:Math.min(point.y,drag.start.y),w:Math.abs(point.x-drag.start.x),h:Math.abs(point.y-drag.start.y)},el=$('#fluidSelectRect');Object.assign(el.style,{left:rect.x+'px',top:rect.y+'px',width:rect.w+'px',height:rect.h+'px'});fluidSelection.clear();drag.prior.forEach(id=>fluidSelection.add(id));for(const n of circuit.nodes){const b=FluidifyModel.bounds(n);if(b.x<rect.x+rect.w&&b.x+b.width>rect.x&&b.y<rect.y+rect.h&&b.y+b.height>rect.y)fluidSelection.add(n.id);}}
    paintFluidMap();
  };
  const finish=e=>{if(!drag)return;const state=drag;drag=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);$('#fluidSelectRect').hidden=true;if(state.type==='nodes'&&state.moved)commitFluid('moved component group');else{if(state.type==='pan'&&!state.moved){fluidSelection.clear();fluidSelected=null;renderFluidInspector();}if(state.type==='box'){fluidSelected=[...fluidSelection][0]||null;renderFluidInspector();}paintFluidMap();persist();}};
  canvas.onpointerup=finish;canvas.onpointercancel=finish;
}
function renderFluidify(){
  const c=fluidCircuit();for(const id of fluidSelection)if(!c.nodes.some(n=>n.id===id))fluidSelection.delete(id);
  const workspace=$('#fluidWorkspace');workspace.innerHTML=`<div class="fluid-heading"><div><div class="eyebrow">FLUID MECHANICAL WORKSPACE</div><h2>Fluidify <span class="fluid-experimental">EXPERIMENTAL</span></h2><p>Map reservoirs, pumps, valves and actuators. Connect fluid ports and organize assemblies.</p></div><div class="fluid-actions"><button class="button" id="fluidImport">Import circuit</button><button class="button" id="fluidExport">Export circuit JSON</button><input type="file" id="fluidFile" accept=".json" hidden></div></div><p class="fluid-help">Concept layout only. Flow, pressure losses, component compatibility and safe operating limits are not simulated.</p><div class="fluid-layout"><aside class="fluid-palette"><h3>Fluid components</h3><p class="fluid-help">Drag to the map or click to add.</p>${Object.entries(FluidifyModel.kinds).map(([key,s])=>`<button class="fluid-preset" draggable="true" data-fluid-kind="${key}"><b>${s.icon}</b>${s.name}</button>`).join('')}</aside><div class="fluid-map-column"><div class="fluid-toolbar"><input id="fluidCircuitName" aria-label="Circuit name" maxlength="200" value="${esc(c.name)}" style="width:145px"><button class="button" id="fluidZoomOut" aria-label="Zoom fluid map out">−</button><span id="fluidZoomLabel"></span><button class="button" id="fluidZoomIn" aria-label="Zoom fluid map in">＋</button><button class="button" id="fluidFit">Fit</button><button class="button" id="fluidBox" aria-pressed="${fluidBoxMode}">Box select</button><label style="font-size:10px"><input type="checkbox" id="fluidAssembly" ${fluidAssembly?'checked':''}> Assembly links</label><button class="button" id="fluidCopyGroup">Duplicate</button><button class="button" id="fluidDeleteGroup">Delete</button><span id="fluidSelectionCount"></span></div><div id="fluidFlowStatus" class="fluid-flow-status">Click an outlet port, then an inlet, to add a hose.</div><div class="fluid-viewport ${fluidBoxMode?'fluid-box-mode':''}" id="fluidViewport"><div class="fluid-world" id="fluidWorld"><svg class="fluid-lines" id="fluidLines" aria-label="Fluid connections"></svg>${c.nodes.map(n=>`<article class="fluid-node" data-fluid-node="${esc(n.id)}"><div class="fluid-node-header"><b>${FluidifyModel.kinds[n.kind].icon}</b><div><strong>${esc(n.name)}</strong><small>${esc(n.medium||'Medium unspecified')} · ×${n.quantity}</small></div></div><div class="fluid-node-ports">${n.ports.map(p=>`<div class="fluid-port-row"><span>${esc(p.name)}</span><span>${p.direction==='in'?'IN':p.direction==='out'?'OUT':'IN / OUT'}</span><button type="button" data-fluid-port="${esc(p.id)}" data-component="${esc(n.id)}" data-direction="${p.direction}" title="${esc(n.name+' / '+p.name+' · '+p.direction)}" aria-label="${esc(n.name+' '+p.name)}"></button></div>`).join('')}</div></article>`).join('')}<div id="fluidSelectRect" class="fluid-select-rect" hidden></div></div>${!c.nodes.length?'<div class="fluid-empty"><strong>Your fluid circuit starts here.</strong><br>Add a reservoir, pump or valve from the fluid component palette.</div>':''}</div><p class="fluid-map-hint">Wheel: zoom · drag empty space: pan · Shift-drag: select a group · Ctrl/Cmd+C/V: duplicate · click a hose to delete it. Dashed lines show assembly parents.</p></div><aside class="fluid-inspector" id="fluidInspector"></aside></div>`;
  workspace.querySelectorAll('[data-fluid-kind]').forEach(b=>{b.onclick=()=>addFluidPart(b.dataset.fluidKind);b.ondragstart=e=>{e.dataTransfer.setData('application/x-partmap-fluid',b.dataset.fluidKind);e.dataTransfer.effectAllowed='copy';};});
  $('#fluidCircuitName').onchange=e=>{if(e.target.value.trim()){c.name=e.target.value.trim();commitFluid('renamed circuit');}};
  $('#fluidZoomIn').onclick=()=>fluidZoom(1.2);$('#fluidZoomOut').onclick=()=>fluidZoom(1/1.2);$('#fluidFit').onclick=fitFluid;
  $('#fluidBox').onclick=()=>{fluidBoxMode=!fluidBoxMode;renderFluidify();};$('#fluidAssembly').onchange=e=>{fluidAssembly=e.target.checked;paintFluidMap();};
  $('#fluidCopyGroup').onclick=duplicateFluidSelection;$('#fluidDeleteGroup').onclick=removeFluidSelection;
  $('#fluidExport').onclick=()=>downloadWorkbenchJSON(FluidifyModel.validate(c),'fluidify-circuit.json');
  $('#fluidImport').onclick=()=>$('#fluidFile').click();$('#fluidFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('Use a circuit JSON smaller than 2 MB.');const next=FluidifyModel.validate(JSON.parse(await file.text()));if(!next)throw Error('Use a fluid circuit JSON document.');if(c.nodes.length&&!confirm('Replace this fluid circuit? Product map and electronics are kept.'))return;project.fluidify=next;fluidSelection.clear();fluidSelected=null;fluidPendingPort=null;commitFluid('imported fluid circuit');fitFluid();}catch(error){toast(error.message);}};
  renderFluidInspector();paintFluidMap();bindFluidCanvas();
}
function initializeFluidify(){
  const nav=document.createElement('button');nav.id='fluidNav';nav.className='rail-item';nav.innerHTML='◌ <span>Fluidify <small>Experimental</small></span>';$('#exportNav').before(nav);
  const workspace=document.createElement('section');workspace.id='fluidWorkspace';workspace.hidden=true;$('#pcbWorkspace').after(workspace);
  const previousWorkbench=showWorkbench;showWorkbench=function(mode){
    if(mode!=='fluidify'){workspace.hidden=true;nav.classList.remove('active');return previousWorkbench(mode);}
    workbenchView='fluidify';workspace.hidden=false;for(const selector of ['.studio','#componentLibrary','#pcbWorkspace','.handoff-banner','.project-heading','.stats'])$(selector).hidden=true;
    $('#mapNav').classList.remove('active');$('#pcbNav').classList.remove('active');nav.classList.add('active');renderFluidify();workspace.scrollIntoView({block:'start'});
  };
  nav.onclick=()=>showWorkbench('fluidify');
  const beforeRender=render;render=function(...args){beforeRender(...args);if(workbenchView==='fluidify')renderFluidify();};
  const beforeBrief=brief;brief=function(){const text=beforeBrief();return project.fluidify?text+'\n\n## Experimental fluid circuit\nConceptual fluid connections; pressure/flow compatibility is not simulated.\n'+JSON.stringify(project.fluidify,null,2):text;};
  document.addEventListener('keydown',e=>{if(workbenchView!=='fluidify'||e.target.closest('input,textarea,select,[contenteditable=true]')||document.querySelector('dialog[open]'))return;const modifier=e.ctrlKey||e.metaKey;if(modifier&&e.key.toLowerCase()==='c'&&fluidSelection.size){e.preventDefault();copyFluidSelection();}else if(modifier&&e.key.toLowerCase()==='v'&&fluidClipboard){e.preventDefault();pasteFluidSelection();}else if(e.key==='Delete'&&fluidSelection.size){e.preventDefault();removeFluidSelection();}else if(e.key==='Escape'){fluidPendingPort=null;renderFluidify();}});
}
initializeFluidify();
